import React from 'react';
import { AlertOctagon, RotateCcw } from 'lucide-react';

export class ErrorBoundary extends React.Component {
  constructor(props) {
    super(props);
    this.state = { hasError: false, error: null, errorInfo: null };
  }

  static getDerivedStateFromError(error) {
    return { hasError: true, error };
  }

  componentDidCatch(error, errorInfo) {
    console.error('SeismoBench ErrorBoundary caught an error:', error, errorInfo);
    this.setState({ errorInfo });
  }

  handleReset = () => {
    this.setState({ hasError: false, error: null, errorInfo: null });
    window.location.reload();
  };

  render() {
    if (this.state.hasError) {
      return (
        <div className="min-h-screen bg-slate-950 text-slate-100 flex items-center justify-center p-6 font-mono">
          <div className="max-w-2xl w-full bg-slate-900 border border-rose-800/80 rounded-2xl p-6 shadow-2xl">
            <div className="flex items-center gap-3 text-rose-400 mb-4">
              <AlertOctagon className="w-8 h-8 shrink-0 text-rose-500" />
              <div>
                <h1 className="text-lg font-bold">SeismoBench Runtime Recovery</h1>
                <p className="text-xs text-slate-400">An unexpected exception was caught in the component tree.</p>
              </div>
            </div>

            <div className="bg-slate-950 p-4 rounded-lg border border-slate-800 text-xs text-rose-300 overflow-x-auto mb-4 font-mono">
              <p className="font-bold mb-1">{this.state.error?.toString()}</p>
              {this.state.errorInfo?.componentStack && (
                <pre className="text-[11px] text-slate-500 whitespace-pre-wrap mt-2">
                  {this.state.errorInfo.componentStack}
                </pre>
              )}
            </div>

            <button
              onClick={this.handleReset}
              className="flex items-center gap-2 px-4 py-2 bg-cyan-600 hover:bg-cyan-500 text-white rounded-lg text-xs font-bold transition-colors shadow-lg shadow-cyan-600/20"
            >
              <RotateCcw className="w-4 h-4" />
              Reset & Reload SeismoBench
            </button>
          </div>
        </div>
      );
    }

    return this.props.children;
  }
}

/**
 * Digital Signal Processing - Digital 2nd-Order High-Pass Butterworth Filter
 * Includes Forward-Backward (filtfilt) zero-phase filtering and baseline detrending.
 */

/**
 * Calculates 2nd-order Butterworth High-Pass Filter IIR coefficients
 * using the Bilinear Transform with frequency pre-warping.
 * 
 * @param {number} fc - Cutoff frequency in Hz
 * @param {number} fs - Sampling frequency in Hz
 * @returns {{b: number[], a: number[]}}
 */
export function calculateButterworthHpCoeffs(fc, fs) {
  // Ensure cutoff is within stable Nyquist range
  const nyquist = fs / 2;
  const clampedFc = Math.max(0.001, Math.min(fc, nyquist * 0.95));

  // Bilinear transform with pre-warping
  const omegaC = Math.PI * clampedFc / fs;
  const K = Math.tan(omegaC);
  const K2 = K * K;
  const sqrt2K = Math.SQRT2 * K;

  const D = 1 + sqrt2K + K2;

  // High-pass transfer function coefficients
  const b0 = 1 / D;
  const b1 = -2 / D;
  const b2 = 1 / D;

  const a1 = (2 * (K2 - 1)) / D;
  const a2 = (1 - sqrt2K + K2) / D;

  return {
    b: [b0, b1, b2],
    a: [1, a1, a2]
  };
}

/**
 * Direct Form II Transposed IIR Filtering
 * @param {number[]} x - Input signal array
 * @param {number[]} b - Feedforward coefficients [b0, b1, b2]
 * @param {number[]} a - Feedback coefficients [1, a1, a2]
 * @returns {number[]} Filtered signal array
 */
export function iirFilter(x, b, a) {
  const n = x.length;
  const y = new Float64Array(n);

  let s1 = 0;
  let s2 = 0;

  for (let i = 0; i < n; i++) {
    const xi = x[i];
    const yi = b[0] * xi + s1;
    s1 = b[1] * xi - a[1] * yi + s2;
    s2 = b[2] * xi - a[2] * yi;
    y[i] = yi;
  }

  return Array.from(y);
}

/**
 * Zero-Phase Forward-Backward Filtering (filtfilt)
 * Eliminates phase shift/lag which is crucial for mechanical alignment.
 * 
 * @param {number[]} x - Input signal
 * @param {number} fc - Cutoff frequency in Hz
 * @param {number} fs - Sampling frequency in Hz
 * @returns {number[]} Zero-phase filtered signal
 */
export function butterworthHighPassZeroPhase(x, fc, fs) {
  if (!x || x.length < 4) return x ? [...x] : [];

  const { b, a } = calculateButterworthHpCoeffs(fc, fs);

  // Forward pass
  const forward = iirFilter(x, b, a);

  // Reverse
  forward.reverse();

  // Backward pass
  const backward = iirFilter(forward, b, a);

  // Reverse back to normal orientation
  backward.reverse();

  return backward;
}

/**
 * Removes DC offset (mean) and linear trend from a signal.
 * @param {number[]} signal
 * @returns {number[]} Detrended signal
 */
export function removeLinearTrend(signal) {
  const n = signal.length;
  if (n <= 1) return [...signal];

  let sumX = 0;
  let sumY = 0;
  let sumXY = 0;
  let sumX2 = 0;

  for (let i = 0; i < n; i++) {
    sumX += i;
    sumY += signal[i];
    sumXY += i * signal[i];
    sumX2 += i * i;
  }

  const slope = (n * sumXY - sumX * sumY) / (n * sumX2 - sumX * sumX);
  const intercept = (sumY - slope * sumX) / n;

  return signal.map((val, i) => val - (slope * i + intercept));
}

/**
 * Taper signal ends using a Tukey (cosine-tapered) window
 * to ensure acceleration cleanly begins and ends at 0.
 * @param {number[]} signal
 * @param {number} taperRatio - fraction of signal tapered at each end (e.g. 0.05 = 5%)
 * @returns {number[]} Tapered signal
 */
export function applyCosineTaper(signal, taperRatio = 0.03) {
  const n = signal.length;
  const m = Math.floor(n * taperRatio);
  if (m <= 0) return [...signal];

  const output = [...signal];
  for (let i = 0; i < m; i++) {
    const factor = 0.5 * (1 - Math.cos((Math.PI * i) / m));
    output[i] *= factor;
    output[n - 1 - i] *= factor;
  }
  return output;
}

import { butterworthHighPassZeroPhase, removeLinearTrend, applyCosineTaper } from './filter.js';

export const G_TO_MM_S2 = 9806.65; // 1 g = 9806.65 mm/s^2

/**
 * Performs numerical double integration from acceleration to velocity to displacement.
 * Applies multi-stage baseline drift correction and high-pass filtering to guarantee
 * that displacement starts at 0.0 mm and returns cleanly to 0.0 mm.
 * 
 * @param {number[]} time - Time array in seconds
 * @param {number[]} rawAccel - Acceleration array (in g's or mm/s^2)
 * @param {Object} options
 * @param {number} options.cutoffFreq - High-pass cutoff frequency in Hz (default: 0.2)
 * @param {boolean} options.isUnitG - True if input is in g, false if in mm/s^2 (default: true)
 * @param {boolean} options.applyTaper - Whether to apply Tukey cosine taper at ends
 * @returns {{
 *   time: number[],
 *   accelFiltered: number[], // in g
 *   velocity: number[],      // in mm/s
 *   displacement: number[],  // in mm
 *   maxDisp: number,
 *   minDisp: number,
 *   peakVelocity: number,
 *   peakAccel: number,
 *   dt: number,
 *   fs: number
 * }}
 */
export function doubleIntegrateDriftFree(time, rawAccel, options = {}) {
  const {
    cutoffFreq = 0.2,
    isUnitG = true,
    applyTaper = true
  } = options;

  const n = time.length;
  if (n < 4) {
    return {
      time,
      accelFiltered: rawAccel,
      velocity: new Array(n).fill(0),
      displacement: new Array(n).fill(0),
      maxDisp: 0,
      minDisp: 0,
      peakVelocity: 0,
      peakAccel: 0,
      dt: 0.02,
      fs: 50
    };
  }

  // Calculate sampling interval dt and sampling frequency fs
  const dt = (time[n - 1] - time[0]) / (n - 1);
  const fs = 1 / dt;

  // 1. Convert to physical acceleration in mm/s^2
  let accelMmS2 = rawAccel.map(a => (isUnitG ? a * G_TO_MM_S2 : a * 1000));

  // 2. Pre-filter acceleration: Detrend + High-Pass filter
  accelMmS2 = removeLinearTrend(accelMmS2);
  accelMmS2 = butterworthHighPassZeroPhase(accelMmS2, cutoffFreq, fs);
  if (applyTaper) {
    accelMmS2 = applyCosineTaper(accelMmS2, 0.03);
  }

  // 3. First Integration: a(t) -> v(t) using Trapezoidal Rule
  const velocityRaw = new Float64Array(n);
  velocityRaw[0] = 0;
  for (let i = 1; i < n; i++) {
    velocityRaw[i] = velocityRaw[i - 1] + 0.5 * (accelMmS2[i - 1] + accelMmS2[i]) * dt;
  }

  // 4. Velocity Baseline Correction: Remove linear trend & High-Pass filter
  let velocityCorrected = removeLinearTrend(Array.from(velocityRaw));
  velocityCorrected = butterworthHighPassZeroPhase(velocityCorrected, cutoffFreq, fs);
  if (applyTaper) {
    velocityCorrected = applyCosineTaper(velocityCorrected, 0.03);
  }

  // Force velocity ends to exactly zero
  velocityCorrected[0] = 0;
  velocityCorrected[n - 1] = 0;

  // 5. Second Integration: v(t) -> x(t) using Trapezoidal Rule
  const dispRaw = new Float64Array(n);
  dispRaw[0] = 0;
  for (let i = 1; i < n; i++) {
    dispRaw[i] = dispRaw[i - 1] + 0.5 * (velocityCorrected[i - 1] + velocityCorrected[i]) * dt;
  }

  // 6. Final Displacement Detrend & Boundary Tapering:
  // Shake table mechanics MUST start at 0.0 mm and return cleanly to 0.0 mm
  let displacement = removeLinearTrend(Array.from(dispRaw));
  displacement = butterworthHighPassZeroPhase(displacement, cutoffFreq * 0.9, fs);

  // Smoothly blend boundary to exactly 0 at start and end
  const boundarySteps = Math.min(Math.floor(n * 0.05), 50);
  for (let i = 0; i < boundarySteps; i++) {
    const ramp = (1 - Math.cos((Math.PI * i) / boundarySteps)) * 0.5;
    displacement[i] *= ramp;
    displacement[n - 1 - i] *= ramp;
  }
  displacement[0] = 0.0;
  displacement[n - 1] = 0.0;

  // Convert filtered acceleration back to g for display
  const accelFilteredG = accelMmS2.map(a => a / G_TO_MM_S2);

  // Calculate waveform metrics
  let maxDisp = -Infinity;
  let minDisp = Infinity;
  let peakVelocity = 0;
  let peakAccel = 0;

  for (let i = 0; i < n; i++) {
    const d = displacement[i];
    const v = Math.abs(velocityCorrected[i]);
    const a = Math.abs(accelFilteredG[i]);

    if (d > maxDisp) maxDisp = d;
    if (d < minDisp) minDisp = d;
    if (v > peakVelocity) peakVelocity = v;
    if (a > peakAccel) peakAccel = a;
  }

  return {
    time,
    accelFiltered: accelFilteredG,
    velocity: velocityCorrected,
    displacement,
    maxDisp,
    minDisp,
    peakVelocity,
    peakAccel,
    dt,
    fs
  };
}

/**
 * Pure JavaScript Cooley-Tukey Radix-2 Fast Fourier Transform (FFT)
 * Computes frequency spectrum, single-sided magnitude, and dominant frequencies.
 */

/**
 * Returns the next power of 2 greater than or equal to n.
 * @param {number} n 
 * @returns {number}
 */
export function nextPowerOf2(n) {
  return Math.pow(2, Math.ceil(Math.log2(n)));
}

/**
 * Bit-reversal permutation for Cooley-Tukey Radix-2 FFT
 */
function bitReverse(real, imag, n) {
  let j = 0;
  for (let i = 0; i < n - 1; i++) {
    if (i < j) {
      // Swap real
      const tempR = real[i];
      real[i] = real[j];
      real[j] = tempR;
      // Swap imag
      const tempI = imag[i];
      imag[i] = imag[j];
      imag[j] = tempI;
    }
    let k = n >> 1;
    while (k <= j) {
      j -= k;
      k >>= 1;
    }
    j += k;
  }
}

/**
 * In-place Cooley-Tukey Radix-2 FFT
 * @param {Float64Array} real
 * @param {Float64Array} imag
 */
export function fftRadix2(real, imag) {
  const n = real.length;
  bitReverse(real, imag, n);

  // Butterfly updates
  for (let len = 2; len <= n; len <<= 1) {
    const halfLen = len >> 1;
    const angle = (-2 * Math.PI) / len;
    const wStepR = Math.cos(angle);
    const wStepI = Math.sin(angle);

    for (let i = 0; i < n; i += len) {
      let wR = 1;
      let wI = 0;

      for (let j = 0; j < halfLen; j++) {
        const uR = real[i + j];
        const uI = imag[i + j];

        const vR = real[i + j + halfLen] * wR - imag[i + j + halfLen] * wI;
        const vI = real[i + j + halfLen] * wI + imag[i + j + halfLen] * wR;

        real[i + j] = uR + vR;
        imag[i + j] = uI + vI;

        real[i + j + halfLen] = uR - vR;
        imag[i + j + halfLen] = uI - vI;

        const nextWR = wR * wStepR - wI * wStepI;
        wI = wR * wStepI + wI * wStepR;
        wR = nextWR;
      }
    }
  }
}

/**
 * Computes single-sided FFT Magnitude Spectrum for real input signal
 * 
 * @param {number[]} signal - Time-domain signal
 * @param {number} fs - Sampling rate in Hz
 * @param {Object} options
 * @param {string} options.window - Window function ('hanning', 'hamming', 'rectangular')
 * @param {number} options.maxFreq - Maximum frequency to return (e.g. 25 Hz)
 * @returns {{
 *   frequencies: number[],
 *   magnitudes: number[],
 *   dominantFreq: number,
 *   peakMagnitude: number
 * }}
 */
export function computeFFT(signal, fs, options = {}) {
  const {
    window = 'hanning',
    maxFreq = 25
  } = options;

  const rawN = signal.length;
  if (rawN < 4) {
    return { frequencies: [0], magnitudes: [0], dominantFreq: 0, peakMagnitude: 0 };
  }

  // Zero-pad to next power of 2
  const N = Math.max(256, nextPowerOf2(rawN));
  const real = new Float64Array(N);
  const imag = new Float64Array(N);

  // Apply Window function to original samples
  for (let i = 0; i < rawN; i++) {
    let winFactor = 1.0;
    if (window === 'hanning') {
      winFactor = 0.5 * (1 - Math.cos((2 * Math.PI * i) / (rawN - 1)));
    } else if (window === 'hamming') {
      winFactor = 0.54 - 0.46 * Math.cos((2 * Math.PI * i) / (rawN - 1));
    }
    real[i] = signal[i] * winFactor;
  }

  // Execute Radix-2 FFT
  fftRadix2(real, imag);

  // Calculate single-sided magnitude spectrum
  const halfN = N / 2;
  const frequencies = [];
  const magnitudes = [];

  let peakMag = 0;
  let dominantFreq = 0;

  // Normalization factor: 2 / rawN (with window coherent gain correction)
  const windowGain = window === 'hanning' ? 0.5 : (window === 'hamming' ? 0.54 : 1.0);
  const scale = 2 / (rawN * windowGain);

  for (let k = 0; k < halfN; k++) {
    const freq = (k * fs) / N;
    if (freq > maxFreq) break;

    // Magnitude
    let mag = Math.sqrt(real[k] * real[k] + imag[k] * imag[k]) * scale;
    if (k === 0) mag /= 2; // DC component

    frequencies.push(freq);
    magnitudes.push(mag);

    // Track peak dominant frequency (skip near-DC < 0.2 Hz)
    if (freq >= 0.2 && mag > peakMag) {
      peakMag = mag;
      dominantFreq = freq;
    }
  }

  return {
    frequencies,
    magnitudes,
    dominantFreq: Number(dominantFreq.toFixed(2)),
    peakMagnitude: Number(peakMag.toFixed(4))
  };
}

/**
 * Telemetry and Signal Comparison Metrics
 * Computes RMSE, Normalized Cross-Correlation (Rxy), and Latency offset (tau).
 */

/**
 * Calculates Root Mean Square Error (RMSE) between two signals
 * @param {number[]} commanded - Expected reference array
 * @param {number[]} measured - Measured sensor array
 * @returns {number} RMSE score
 */
export function calculateRMSE(commanded, measured) {
  const n = Math.min(commanded.length, measured.length);
  if (n === 0) return 0;

  let sumSqErr = 0;
  for (let i = 0; i < n; i++) {
    const err = commanded[i] - measured[i];
    sumSqErr += err * err;
  }

  return Math.sqrt(sumSqErr / n);
}

/**
 * Computes Normalized Cross-Correlation and estimates phase lag/latency in milliseconds.
 * 
 * @param {number[]} x - Commanded signal
 * @param {number[]} y - Measured signal
 * @param {number} dt - Sampling time step in seconds
 * @param {number} maxLagSec - Maximum lag window to search (default 0.2s = 200ms)
 * @returns {{
 *   correlationPercent: number, // Rxy at zero or peak lag (0 - 100%)
 *   latencyMs: number,          // Phase delay in ms (positive means measured lags behind commanded)
 *   peakRxy: number             // Normalized max cross-correlation (-1 to 1)
 * }}
 */
export function calculateCrossCorrelationAndLag(x, y, dt, maxLagSec = 0.25) {
  const n = Math.min(x.length, y.length);
  if (n < 8 || dt <= 0) {
    return { correlationPercent: 100, latencyMs: 0, peakRxy: 1 };
  }

  // Calculate means
  let meanX = 0;
  let meanY = 0;
  for (let i = 0; i < n; i++) {
    meanX += x[i];
    meanY += y[i];
  }
  meanX /= n;
  meanY /= n;

  // Calculate variances
  let varX = 0;
  let varY = 0;
  for (let i = 0; i < n; i++) {
    const dx = x[i] - meanX;
    const dy = y[i] - meanY;
    varX += dx * dx;
    varY += dy * dy;
  }

  const denom = Math.sqrt(varX * varY);
  if (denom === 0) {
    return { correlationPercent: 100, latencyMs: 0, peakRxy: 1 };
  }

  const maxLagSteps = Math.min(Math.floor(maxLagSec / dt), Math.floor(n / 4));
  let bestR = -Infinity;
  let bestLagSteps = 0;
  let zeroLagR = 0;

  for (let lag = -maxLagSteps; lag <= maxLagSteps; lag++) {
    let sumProd = 0;
    let count = 0;

    for (let i = 0; i < n; i++) {
      const j = i + lag;
      if (j >= 0 && j < n) {
        sumProd += (x[i] - meanX) * (y[j] - meanY);
        count++;
      }
    }

    if (count > 0) {
      const r = sumProd / denom;
      if (lag === 0) zeroLagR = r;
      if (r > bestR) {
        bestR = r;
        bestLagSteps = lag;
      }
    }
  }

  const latencyMs = bestLagSteps * dt * 1000;
  const correlationPercent = Math.max(0, Math.min(100, bestR * 100));

  return {
    correlationPercent: Number(correlationPercent.toFixed(1)),
    latencyMs: Number(latencyMs.toFixed(1)),
    peakRxy: Number(bestR.toFixed(4)),
    zeroLagR: Number(zeroLagR.toFixed(4))
  };
}

/**
 * Checks if displacement profile exceeds physical carriage stroke limits.
 * Calculates safety margins and recommended scaling factor if clipping occurs.
 * 
 * @param {number[]} displacement - Table displacement array in mm
 * @param {number} strokeLimitMm - Single-sided stroke limit (+/- mm, e.g. 40mm)
 * @returns {{
 *   exceedsLimit: boolean,
 *   maxPositiveDisp: number,
 *   maxNegativeDisp: number,
 *   peakAbsoluteDisp: number,
 *   clipMargin: number,
 *   recommendedScale: number
 * }}
 */
export function checkPhysicalLimits(displacement, strokeLimitMm = 40) {
  let maxPos = 0;
  let maxNeg = 0;

  for (let i = 0; i < displacement.length; i++) {
    const d = displacement[i];
    if (d > maxPos) maxPos = d;
    if (d < maxNeg) maxNeg = d;
  }

  const peak = Math.max(Math.abs(maxPos), Math.abs(maxNeg));
  const exceeds = peak > strokeLimitMm;
  const margin = strokeLimitMm - peak;
  const recommendedScale = exceeds ? Number((strokeLimitMm / peak * 0.95).toFixed(3)) : 1.0;

  return {
    exceedsLimit: exceeds,
    maxPositiveDisp: Number(maxPos.toFixed(2)),
    maxNegativeDisp: Number(maxNeg.toFixed(2)),
    peakAbsoluteDisp: Number(peak.toFixed(2)),
    clipMargin: Number(margin.toFixed(2)),
    recommendedScale
  };
}

