  const n = Math.floor(duration / dt);
  const time = [];
  const accel = [];
  const pga = 0.82; // 0.82g peak

  // Envelope peak centered around t = 7.5s
  for (let i = 0; i < n; i++) {
    const t = i * dt;
    time.push(Number(t.toFixed(3)));

    let val = 0;
    if (t >= 3.0 && t <= 20.0) {
