      const microTremors = 0.12 * Math.sin(2 * Math.PI * 7.5 * t) * Math.exp(-0.08 * Math.pow(t - 8.0, 2));

      val = (pulse1 + pulse2 + pulse3 + microTremors) * pga * 0.95;
